const std=@import("std");
export fn lorentz_transformation_four_vector(v:[*]const i64,n:usize)callconv(.c)f64{if(n!=6)return -1e300;const vel=v[0];const s=v[1];const t=v[2];const x=v[3];const y=v[4];const z=v[5];if(vel<1 or vel>200000000 or s<0 or s>3 or t< -1000000 or t>1000000 or x< -100000000 or x>100000000 or y< -100000000 or y>100000000 or z< -100000000 or z>100000000)return -1e300;const b=@as(f64,@floatFromInt(vel))/299792458.0;const g=1.0/std.math.sqrt(1-b*b);const ct=(@as(f64,@floatFromInt(t))/1e6)*299792458.0;const xx=@as(f64,@floatFromInt(x))/100.0;const yy=@as(f64,@floatFromInt(y))/100.0;const zz=@as(f64,@floatFromInt(z))/100.0;const out=[_]f64{g*ct-g*b*xx,-g*b*ct+g*xx,yy,zz};return out[@intCast(s)];}
